style:
.sirb-upload-grid {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
	gap: 16px;
	margin: 4px 0 12px 0;
}

.sirb-upload-card {
	display: flex;
	align-items: flex-start;
	gap: 14px;
	padding: 18px;
	border: 1px solid var(--border-color);
	border-radius: var(--border-radius-lg, 10px);
	background: var(--card-bg, var(--fg-color));
	text-decoration: none;
	transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.sirb-upload-card:hover {
	border-color: var(--primary);
	box-shadow: var(--shadow-md, 0 4px 12px rgba(0,0,0,0.08));
	transform: translateY(-1px);
	text-decoration: none;
}

.sirb-upload-icon {
	flex-shrink: 0;
	width: 40px;
	height: 40px;
	border-radius: 8px;
	display: flex;
	align-items: center;
	justify-content: center;
}

.sirb-upload-icon svg {
	width: 22px;
	height: 22px;
}

.sirb-icon-blue {
	background: rgba(59, 130, 246, 0.12);
	color: #3b82f6;
}

.sirb-icon-purple {
	background: rgba(139, 92, 246, 0.12);
	color: #8b5cf6;
}

.sirb-upload-body {
	flex: 1;
	min-width: 0;
}

.sirb-upload-title {
	font-size: 14px;
	font-weight: 600;
	color: var(--text-color);
	margin-bottom: 4px;
}

.sirb-upload-desc {
	font-size: 12.5px;
	line-height: 1.45;
	color: var(--text-muted);
}

.sirb-upload-arrow {
	flex-shrink: 0;
	align-self: center;
	color: var(--text-muted);
	transition: transform 0.15s ease, color 0.15s ease;
}

.sirb-upload-card:hover .sirb-upload-arrow {
	transform: translateX(3px);
	color: var(--primary);
}

.sirb-upload-arrow svg {
	width: 18px;
	height: 18px;
}
